-- PostgreSQL 14+; run only in a fresh demonstration database.
BEGIN;
CREATE SCHEMA IF NOT EXISTS library;
SET search_path TO library,public;
CREATE TABLE IF NOT EXISTS branches(branch_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,branch_code varchar(20) UNIQUE NOT NULL,branch_name varchar(120) NOT NULL,address varchar(200) NOT NULL);
CREATE TABLE IF NOT EXISTS staff(staff_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,employee_no varchar(20) UNIQUE NOT NULL,full_name varchar(120) NOT NULL,branch_id bigint NOT NULL REFERENCES branches,staff_role varchar(25) NOT NULL CHECK(staff_role IN ('LIBRARIAN','ASSISTANT','MANAGER')),active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS borrowers(borrower_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,library_card varchar(30) UNIQUE NOT NULL,full_name varchar(120) NOT NULL,email varchar(160) UNIQUE NOT NULL,joined_at date NOT NULL DEFAULT CURRENT_DATE,active boolean NOT NULL DEFAULT true);
CREATE TABLE IF NOT EXISTS categories(category_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,category_name varchar(80) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS authors(author_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,author_name varchar(140) UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS books(book_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,isbn varchar(20) UNIQUE NOT NULL,title varchar(180) NOT NULL,category_id bigint NOT NULL REFERENCES categories,publication_year integer CHECK(publication_year BETWEEN 1500 AND 2100),publisher varchar(120),metadata jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(metadata)='object'));
CREATE TABLE IF NOT EXISTS book_authors(book_id bigint REFERENCES books ON DELETE CASCADE,author_id bigint REFERENCES authors,PRIMARY KEY(book_id,author_id));
CREATE TABLE IF NOT EXISTS book_copies(copy_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,book_id bigint NOT NULL REFERENCES books,branch_id bigint NOT NULL REFERENCES branches,barcode varchar(35) UNIQUE NOT NULL,condition_status varchar(15) NOT NULL DEFAULT 'CIRCULATING' CHECK(condition_status IN ('CIRCULATING','REPAIR','WITHDRAWN')),acquired_on date NOT NULL DEFAULT CURRENT_DATE);
CREATE TABLE IF NOT EXISTS loans(loan_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,copy_id bigint NOT NULL REFERENCES book_copies,borrower_id bigint NOT NULL REFERENCES borrowers,checked_out_by bigint NOT NULL REFERENCES staff,loaned_at timestamptz NOT NULL DEFAULT clock_timestamp(),due_at timestamptz NOT NULL,returned_at timestamptz,checked_in_by bigint REFERENCES staff,notes text,CONSTRAINT loans_due_after_start CHECK(due_at>loaned_at),CONSTRAINT loans_return_after_start CHECK(returned_at IS NULL OR returned_at>=loaned_at),CONSTRAINT loans_return_pair CHECK((returned_at IS NULL)=(checked_in_by IS NULL)));
CREATE UNIQUE INDEX IF NOT EXISTS ux_loans_one_open_per_copy ON loans(copy_id) WHERE returned_at IS NULL;
CREATE TABLE IF NOT EXISTS fines(fine_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,loan_id bigint UNIQUE NOT NULL REFERENCES loans,assessed_amount numeric(10,2) NOT NULL CHECK(assessed_amount>0),assessed_at timestamptz NOT NULL DEFAULT clock_timestamp(),assessed_by bigint NOT NULL REFERENCES staff);
CREATE TABLE IF NOT EXISTS fine_payments(payment_id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,fine_id bigint NOT NULL REFERENCES fines,amount numeric(10,2) NOT NULL CHECK(amount>0),received_at timestamptz NOT NULL DEFAULT clock_timestamp(),collected_by bigint NOT NULL REFERENCES staff,receipt_ref varchar(40) UNIQUE);
CREATE OR REPLACE VIEW v_catalogue AS SELECT b.book_id,b.isbn,b.title,c.category_name,COALESCE(string_agg(DISTINCT a.author_name,', '),'') authors,COUNT(DISTINCT cp.copy_id) total_copies,COUNT(DISTINCT cp.copy_id) FILTER(WHERE cp.condition_status='CIRCULATING' AND NOT EXISTS(SELECT 1 FROM loans l WHERE l.copy_id=cp.copy_id AND l.returned_at IS NULL)) available_copies FROM books b JOIN categories c ON c.category_id=b.category_id LEFT JOIN book_authors ba ON ba.book_id=b.book_id LEFT JOIN authors a ON a.author_id=ba.author_id LEFT JOIN book_copies cp ON cp.book_id=b.book_id GROUP BY b.book_id,b.isbn,b.title,c.category_name;
CREATE OR REPLACE VIEW v_loan_status AS SELECT l.loan_id,l.borrower_id,l.copy_id,l.loaned_at,l.due_at,l.returned_at,CASE WHEN l.returned_at IS NOT NULL THEN 'RETURNED' WHEN l.due_at<clock_timestamp() THEN 'OVERDUE' ELSE 'OPEN' END loan_status,GREATEST(0,COALESCE(l.returned_at::date,CURRENT_DATE)-l.due_at::date) overdue_days FROM loans l;
CREATE OR REPLACE VIEW v_fine_balances AS SELECT f.fine_id,f.loan_id,f.assessed_amount,COALESCE(SUM(fp.amount),0)::numeric(10,2) paid_amount,(f.assessed_amount-COALESCE(SUM(fp.amount),0))::numeric(10,2) outstanding_amount FROM fines f LEFT JOIN fine_payments fp ON fp.fine_id=f.fine_id GROUP BY f.fine_id,f.loan_id,f.assessed_amount;
CREATE OR REPLACE FUNCTION checkout_book(p_copy_id bigint,p_borrower_id bigint,p_staff_id bigint,p_days integer DEFAULT 14) RETURNS bigint LANGUAGE plpgsql SET search_path=library,public AS $$
DECLARE v_condition text;v_active boolean;v_staff_active boolean;v_new_loan bigint;
BEGIN
 IF p_days<1 OR p_days>60 THEN RAISE EXCEPTION 'Loan length must be between 1 and 60 days';END IF;
 SELECT condition_status INTO v_condition FROM book_copies WHERE copy_id=p_copy_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Copy % does not exist',p_copy_id;END IF;
 IF v_condition<>'CIRCULATING' THEN RAISE EXCEPTION 'Copy % is not circulating',p_copy_id;END IF;
 SELECT active INTO v_active FROM borrowers WHERE borrower_id=p_borrower_id;
 IF NOT FOUND OR NOT v_active THEN RAISE EXCEPTION 'Borrower % is not active',p_borrower_id;END IF;
 SELECT active INTO v_staff_active FROM staff WHERE staff_id=p_staff_id;
 IF NOT FOUND OR NOT v_staff_active THEN RAISE EXCEPTION 'Staff member % is not active',p_staff_id;END IF;
 IF EXISTS(SELECT 1 FROM loans WHERE copy_id=p_copy_id AND returned_at IS NULL) THEN RAISE EXCEPTION 'Copy % is already on loan',p_copy_id;END IF;
 INSERT INTO loans(copy_id,borrower_id,checked_out_by,loaned_at,due_at) VALUES(p_copy_id,p_borrower_id,p_staff_id,clock_timestamp(),clock_timestamp()+make_interval(days=>p_days)) RETURNING loan_id INTO v_new_loan;
 RETURN v_new_loan;
END $$;
CREATE OR REPLACE FUNCTION return_book(p_loan_id bigint,p_staff_id bigint,p_returned_at timestamptz DEFAULT clock_timestamp()) RETURNS TABLE(returned_loan_id bigint,created_fine_id bigint,fine_amount numeric) LANGUAGE plpgsql SET search_path=library,public AS $$
DECLARE v_loan loans%ROWTYPE;v_days integer;v_fine_id bigint;v_amount numeric(10,2);
BEGIN
 PERFORM 1 FROM staff WHERE staff_id=p_staff_id AND active=true;
 IF NOT FOUND THEN RAISE EXCEPTION 'Staff member % is not active',p_staff_id;END IF;
 SELECT * INTO v_loan FROM loans WHERE loan_id=p_loan_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Loan % does not exist',p_loan_id;END IF;
 IF v_loan.returned_at IS NOT NULL THEN RAISE EXCEPTION 'Loan % already returned',p_loan_id;END IF;
 IF p_returned_at<v_loan.loaned_at THEN RAISE EXCEPTION 'Return time earlier than checkout';END IF;
 UPDATE loans SET returned_at=p_returned_at,checked_in_by=p_staff_id WHERE loan_id=p_loan_id;
 v_days:=GREATEST(0,p_returned_at::date-v_loan.due_at::date);
 v_amount:=v_days*50.00;
 IF v_amount>0 THEN INSERT INTO fines(loan_id,assessed_amount,assessed_by) VALUES(p_loan_id,v_amount,p_staff_id) RETURNING fine_id INTO v_fine_id;END IF;
 RETURN QUERY SELECT p_loan_id,v_fine_id,v_amount;
END $$;
CREATE OR REPLACE FUNCTION pay_fine(p_fine_id bigint,p_amount numeric,p_staff_id bigint,p_receipt_ref text) RETURNS bigint LANGUAGE plpgsql SET search_path=library,public AS $$
DECLARE v_fine fines%ROWTYPE;v_paid numeric(10,2);v_payment_id bigint;
BEGIN
 IF p_amount<=0 THEN RAISE EXCEPTION 'Payment must be positive';END IF;
 PERFORM 1 FROM staff WHERE staff_id=p_staff_id AND active=true;
 IF NOT FOUND THEN RAISE EXCEPTION 'Staff member % is not active',p_staff_id;END IF;
 SELECT * INTO v_fine FROM fines WHERE fine_id=p_fine_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Fine % does not exist',p_fine_id;END IF;
 SELECT COALESCE(SUM(amount),0) INTO v_paid FROM fine_payments WHERE fine_id=p_fine_id;
 IF v_paid+p_amount>v_fine.assessed_amount THEN RAISE EXCEPTION 'Payment exceeds outstanding balance';END IF;
 INSERT INTO fine_payments(fine_id,amount,collected_by,receipt_ref) VALUES(p_fine_id,p_amount,p_staff_id,p_receipt_ref) RETURNING payment_id INTO v_payment_id;
 RETURN v_payment_id;
END $$;
COMMIT;
